using Inventory=suitecut::CoverageScriptInventory;using Controls=suitecut::CoverageControls;using Dict=Inventory::Dict;
Dict Parse(const std::string& json){auto value=CefParseJSON(json,JSON_PARSER_RFC);assert(value);return value->GetDictionary();}
Dict Script(const std::string& id,const std::string& url="http://actual/source.js",int context=7){auto p=CefDictionaryValue::Create();p->SetString("scriptId",id);p->SetString("url",url);p->SetInt("executionContextId",context);return p;}
struct Harness{
 struct Call{std::string method;Controls::ProtocolReply reply;};
 double now=1;Inventory inventory;std::deque<Call> calls;std::unique_ptr<Controls> controls;int replies=0;bool success=false;std::string result;
 Harness(){Controls::Hooks hooks;hooks.now=[this](){return now;};hooks.root_target_only=[](){return true;};hooks.author_context=[](int c){return c==7;};hooks.debugger_acquire=[this](double,Controls::ProtocolReply reply){calls.push_back({"actual-acquire",std::move(reply)});return true;};hooks.debugger_release=[this](double,Controls::ProtocolReply reply){calls.push_back({"actual-release",std::move(reply)});return true;};hooks.script_inventory=[this](double deadline,std::vector<Dict>& output,std::string& error){return inventory.Snapshot("",output,error,deadline,[](){return 1.;});};hooks.send=[this](const std::string& method,Dict,double,Controls::ProtocolReply reply){calls.push_back({method,std::move(reply)});return true;};controls=std::make_unique<Controls>(std::move(hooks));}
 void Handle(const char* action){auto p=CefDictionaryValue::Create();p->SetString("action",action);controls->Handle(++owner,p,100,[this](bool ok,const std::string&,const std::string& json){++replies;success=ok;result=json;});}
 void Ack(const std::string& method,Dict value=nullptr){auto found=std::find_if(calls.begin(),calls.end(),[&](const auto& call){return call.method==method;});assert(found!=calls.end());auto call=std::move(*found);calls.erase(found);call.reply(true,value?value:CefDictionaryValue::Create(),"");}
 int owner=0;
};
