 {Harness h;h.inventory.Observe("Debugger.scriptParsed",Script("native"),"");h.inventory.Observe("Debugger.scriptParsed",Script("author"),"");assert(h.inventory.MarkNative("",7,"native"));h.Handle("startJS");h.Ack("actual-acquire");assert(h.controls->PhysicalCount()==2);h.Ack("Debugger.getScriptSource",Parse(R"({"scriptSource":"actual();"})"));h.Ack("Profiler.enable");h.Ack("Profiler.startPreciseCoverage");h.Handle("stopJS");h.Ack("Profiler.takePreciseCoverage",Parse(R"({"result":[{"scriptId":"native","functions":[]},{"scriptId":"author","functions":[]}]})"));h.Ack("Profiler.stopPreciseCoverage");h.Ack("Profiler.disable");h.Ack("actual-release");auto output=CefParseJSON(h.result,JSON_PARSER_RFC);assert(h.success&&output->GetList()->GetSize()==1&&output->GetList()->GetDictionary(0)->GetString("scriptId")=="author");++groups;}
